#!/usr/bin/env python3
"""Validate the `pi` key in package.json against pi's manifest contract.

pi reads it through dist/core/pi-manifest.js: an object whose extensions /
skills / prompts / themes fields are arrays of strings. A field of any other
shape is dropped and no diagnostic is emitted, so a typo here registers zero
resources and looks exactly like success. Usage: check-manifest.py <repo-root>
"""

import json
import sys
from pathlib import Path

OVERRIDE_PREFIXES = ("!", "+", "-")


def main(root: Path) -> None:
    pkg = json.loads((root / "package.json").read_text())

    manifest = pkg.get("pi")
    if not isinstance(manifest, dict):
        raise SystemExit(
            "FAIL: package.json has no `pi` object; `pi install` would register 0 resources"
        )

    skills = manifest.get("skills")
    if not isinstance(skills, list) or not skills:
        raise SystemExit("FAIL: pi.skills must be a non-empty array of strings")
    if not all(isinstance(entry, str) for entry in skills):
        raise SystemExit(
            "FAIL: pi.skills must contain only strings (pi drops a mixed array silently)"
        )

    # Entries starting with ! + or - are override patterns, not sources. Every
    # remaining entry must exist: pi resolves a missing source to nothing and
    # says nothing about it.
    sources = [e for e in skills if not e.startswith(OVERRIDE_PREFIXES)]
    if not sources:
        raise SystemExit("FAIL: pi.skills has only override patterns and no source path")
    for entry in sources:
        if not (root / entry).exists():
            raise SystemExit(f"FAIL: pi.skills entry does not exist: {entry}")

    for field in ("extensions", "prompts", "themes"):
        value = manifest.get(field)
        if value is None:
            continue
        if not isinstance(value, list) or not all(isinstance(e, str) for e in value):
            raise SystemExit(f"FAIL: pi.{field} must be an array of strings")


if __name__ == "__main__":
    main(Path(sys.argv[1]))
